package modkit

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"go/format"
	"net/http"
	"sort"
	"strconv"
	"strings"
)

// formatGo renders emitted Go through the standard formatter. Emitters build
// source by string concatenation; running the formatter once here means a
// generated file can never disagree with gofmt, and a syntax error is caught
// inside the transaction instead of at the next build.
func formatGo(file *GeneratedFile) (*GeneratedFile, error) {
	if !strings.HasSuffix(file.Path, ".go") {
		return file, nil
	}
	formatted, err := format.Source([]byte(file.Content))
	if err != nil {
		return nil, fmt.Errorf("%s: generated Go does not parse: %w", file.Path, err)
	}
	file.Content = string(formatted)
	return file, nil
}

// GeneratedFile is one deterministic registry-owned output emitted by the
// generator pipeline. Every path is tool-owned; authored modules never claim
// these targets.
type GeneratedFile struct {
	Path    string
	Content string
}

// genHeader is the shared DO-NOT-EDIT banner for generated Go files. The
// indexSHA ties the output to the exact gogogadget.lock.json it was rendered
// from, so drift is detectable.
func genHeader(modulePath string, lock Lock) string {
	var b strings.Builder
	b.WriteString("// Code generated by ggg sync; DO NOT EDIT.\n")
	b.WriteString("//\n")
	fmt.Fprintf(&b, "// index: %s\n", indexSHA(lock))
	fmt.Fprintf(&b, "// registry: %s\n", lock.RegistryCommit)
	b.WriteString("\n")
	_ = modulePath
	return b.String()
}

// indexSHA is the deterministic digest of the resolved module graph. It changes
// whenever any selected module's revision, contract, or set changes.
func indexSHA(lock Lock) string {
	h := sha256.New()
	for _, id := range lock.Order {
		h.Write([]byte(id))
		h.Write([]byte{0})
	}
	for _, m := range lock.Modules {
		fmt.Fprintf(h, "%s@%d#%d\x00", m.ID, m.Revision, m.Contract)
	}
	h.Write([]byte(lock.RegistryCommit))
	return hex.EncodeToString(h.Sum(nil))
}

// GenerateAll renders every registry-owned output for the resolved graph. It
// is a pure function of (modulePath, lock, graph): identical inputs always
// produce byte-identical outputs, and the file list is sorted by path.
func GenerateAll(ctx context.Context, modulePath string, lock Lock, graph []Manifest) ([]GeneratedFile, error) {
	emitters := []struct {
		name string
		fn   func(context.Context, string, Lock, []Manifest) (*GeneratedFile, error)
	}{
		{"bootstrap", emitBootstrapRegistry},
		{"testhost", emitTestHostRegistry},
		{"routes", emitRoutesRegistry},
		{"chrome", emitChromeRegistry},
		{"settings_nav", emitSettingsNavigationRegistry},
		{"shell_slots", emitShellSlotsRegistry},
		{"locales", emitLocalesRegistry},
		{"catalog_en", emitCatalogRegistry},
		{"catalog_es", emitCatalogRegistryES},
		{"openapi", emitOpenAPIRegistry},
		{"queries", emitQueriesRegistry},
		{"static", emitStaticRegistry},
		{"ui_components", emitUIComponentsRegistry},
		{"styles", emitStylesRegistry},
		{"content", emitContentRegistry},
		{"config", emitConfigRegistry},
		{"jobs", emitJobsRegistry},
	}
	files := make([]GeneratedFile, 0, len(emitters))
	for _, emitter := range emitters {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		file, err := emitter.fn(ctx, modulePath, lock, graph)
		if err != nil {
			return nil, fmt.Errorf("generate %s: %w", emitter.name, err)
		}
		if file != nil {
			if !isGeneratedOutput(file.Path) {
				return nil, fmt.Errorf("emitter %s produced non-generated path %s", emitter.name, file.Path)
			}
			formatted, err := formatGo(file)
			if err != nil {
				return nil, fmt.Errorf("generate %s: %w", emitter.name, err)
			}
			files = append(files, *formatted)
		}
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Path < files[j].Path })
	return files, nil
}

// qualifyPackage turns a module-relative package path from a manifest into an
// import path in the target module. Manifests never carry absolute import paths:
// a derivative's Go module path differs from the canonical one, so an absolute
// path baked into distributed data would not compile once installed.
func qualifyPackage(modulePath, pkg string) string {
	return modulePath + "/" + strings.Trim(pkg, "/")
}

// resolveTypeImport resolves a declared provide-type import. An external module
// path is domain-qualified (its first segment contains a dot) and is used
// verbatim; anything else is module-relative and qualified against the target
// module, so a derivative imports its own copy rather than the upstream one.
func resolveTypeImport(modulePath, declared string) string {
	trimmed := strings.Trim(declared, "/")
	first := trimmed
	if i := strings.Index(trimmed, "/"); i >= 0 {
		first = trimmed[:i]
	}
	if strings.Contains(first, ".") {
		return trimmed
	}
	return qualifyPackage(modulePath, trimmed)
}

// bootstrapFixedImports are the packages the generated bootstrap always imports.
// A declared type import naming one of these is skipped rather than resolved,
// because a dotless stdlib path is indistinguishable from a module-relative one.
var bootstrapFixedImports = map[string]struct{}{
	"context":  {},
	"errors":   {},
	"fmt":      {},
	"net/http": {},
}

// DefaultJobAttempts mirrors jobs.DefaultMaxAttempts and the jobs.max_attempts
// column default. A declaration that omits a budget gets this.
const DefaultJobAttempts = 8

// httpHandlerCapability is the one structurally special capability: the module
// providing it is what the runtime serves.
const httpHandlerCapability = "http.handler"

// capabilityField turns a capability name into the exported Runtime field that
// carries it. Capabilities are globally unique (the namespace preflight enforces
// it), so deriving the field from the capability — not from the module's own
// field name — keeps two modules that both provide a "Client" from colliding.
func capabilityField(capability string) string {
	var b strings.Builder
	for _, segment := range strings.FieldsFunc(capability, func(r rune) bool {
		return r == '.' || r == '-' || r == '_' || r == '/'
	}) {
		if initialism, ok := goInitialisms[segment]; ok {
			b.WriteString(initialism)
			continue
		}
		b.WriteString(strings.ToUpper(segment[:1]))
		b.WriteString(segment[1:])
	}
	return b.String()
}

// goInitialisms keeps generated field names idiomatic. Go spells initialisms in
// one case, and so does the rest of this codebase (AppURL, LLMAPIKey), so the
// generator must not emit HttpHandler or LlmCompleter.
var goInitialisms = map[string]string{
	"api":   "API",
	"csv":   "CSV",
	"db":    "DB",
	"dsn":   "DSN",
	"html":  "HTML",
	"http":  "HTTP",
	"https": "HTTPS",
	"id":    "ID",
	"json":  "JSON",
	"llm":   "LLM",
	"sql":   "SQL",
	"ui":    "UI",
	"url":   "URL",
	"uuid":  "UUID",
	"yaml":  "YAML",
}

func goImportName(pkg string) string {
	base := pkg
	if i := strings.LastIndex(pkg, "/"); i >= 0 {
		base = pkg[i+1:]
	}
	if i := strings.LastIndex(base, "-"); i >= 0 {
		base = base[:i]
	}
	return base
}

// goVar returns a deterministic Go variable name for a module ID.
func goVar(id string) string {
	name := strings.ReplaceAll(id, "/", "_")
	name = strings.ReplaceAll(name, "-", "_")
	return name + "Module"
}

func goString(s string) string {
	return fmt.Sprintf("%q", s)
}

// orderedModules returns the graph modules in lock topological order.
func orderedModules(lock Lock, graph []Manifest) []Manifest {
	byID := make(map[string]Manifest, len(graph))
	for _, m := range graph {
		byID[m.ID] = m
	}
	ordered := make([]Manifest, 0, len(lock.Order))
	for _, id := range lock.Order {
		if m, ok := byID[id]; ok {
			ordered = append(ordered, m)
		}
	}
	return ordered
}

// collectRootNeeds returns needs whose capability is not provided by any
// module in the graph; these are ambient values supplied by Options.
func collectRootNeeds(lock Lock, graph []Manifest) []RuntimeNeed {
	provided := make(map[string]bool)
	for _, m := range orderedModules(lock, graph) {
		if m.Runtime.System != nil {
			for _, p := range m.Runtime.System.Provides {
				provided[p.Capability] = true
			}
		}
	}
	seen := make(map[string]bool)
	needs := make([]RuntimeNeed, 0)
	for _, m := range orderedModules(lock, graph) {
		if m.Runtime.System == nil {
			continue
		}
		for _, n := range m.Runtime.System.Needs {
			if provided[n.Capability] || seen[n.Field] {
				continue
			}
			seen[n.Field] = true
			needs = append(needs, n)
		}
	}
	return needs
}

func isRootCapability(rootNeeds []RuntimeNeed, need RuntimeNeed) bool {
	for _, n := range rootNeeds {
		if n.Capability == need.Capability && n.Field == need.Field {
			return true
		}
	}
	return false
}

// emitBootstrapRegistry renders internal/modules/bootstrap_registry_gen.go,
// the only file that imports every selected system module. It generates direct
// constructor calls in topological order so an incorrect manifest declaration
// becomes a compile error on a named generated line.
func emitBootstrapRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	modules := orderedModules(lock, graph)
	rootNeeds := collectRootNeeds(lock, graph)
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package modules\n\n")
	needsErrors := false
	for _, m := range modules {
		if m.Runtime.System != nil && m.Runtime.System.Stop {
			needsErrors = true
		}
	}
	b.WriteString("import (\n")
	b.WriteString("\t\"context\"\n")
	if needsErrors {
		b.WriteString("\t\"errors\"\n")
	}
	b.WriteString("\t\"fmt\"\n")
	b.WriteString("\t\"net/http\"\n")
	b.WriteString("\n")
	imports := []string{"\tapphost \"" + modulePath + "/internal/apphost\"\n"}
	seenImports := make(map[string]struct{})
	for _, m := range modules {
		if m.Runtime.System == nil || m.Runtime.System.Package == "" {
			continue
		}
		qualified := qualifyPackage(modulePath, m.Runtime.System.Package)
		if _, ok := seenImports[qualified]; !ok {
			seenImports[qualified] = struct{}{}
			imports = append(imports, "\t"+goImportName(qualified)+" \""+qualified+"\"\n")
		}
		for _, extra := range m.Runtime.System.TypeImports {
			if _, fixed := bootstrapFixedImports[strings.Trim(extra, "/")]; fixed {
				// Already imported unconditionally below; resolving it would also
				// mistake a dotless stdlib path for a module-relative one.
				continue
			}
			resolved := resolveTypeImport(modulePath, extra)
			if _, ok := seenImports[resolved]; ok {
				continue
			}
			seenImports[resolved] = struct{}{}
			imports = append(imports, "\t"+goImportName(resolved)+" \""+resolved+"\"\n")
		}
	}
	sort.Strings(imports)
	for _, line := range imports {
		b.WriteString(line)
	}
	b.WriteString(")\n\n")

	b.WriteString("// Options carries the ambient values the selected closure boots with.\n")
	b.WriteString("type Options struct {\n")
	for _, need := range rootNeeds {
		fmt.Fprintf(&b, "\t%s %s\n", need.Field, need.Type)
	}
	b.WriteString("}\n\n")
	b.WriteString("// Runtime is the booted module closure. Every capability the selected\n")
	b.WriteString("// graph provides is reachable here, so consumers take typed values rather\n")
	b.WriteString("// than reconstructing providers.\n")
	// One capability is structural: whichever module provides http.handler is
	// what Handler() returns, so the runtime composes a servable handler instead
	// of carrying a field nothing ever assigns.
	handlerField := ""
	for _, m := range modules {
		if m.Runtime.System == nil {
			continue
		}
		for _, provide := range m.Runtime.System.Provides {
			if provide.Capability == httpHandlerCapability {
				handlerField = capabilityField(provide.Capability)
			}
		}
	}

	b.WriteString("type Runtime struct {\n")
	b.WriteString("\tstart []func(context.Context) error\n")
	b.WriteString("\tstop  []apphost.Stop\n")
	provided := make([]string, 0)
	for _, m := range modules {
		if m.Runtime.System == nil {
			continue
		}
		for _, provide := range m.Runtime.System.Provides {
			field := capabilityField(provide.Capability)
			if !validIdentifier(field) {
				return nil, fmt.Errorf("module %s: capability %q does not yield a Go field", m.ID, provide.Capability)
			}
			provided = append(provided, fmt.Sprintf("\t%s %s\n", field, provide.Type))
		}
	}
	sort.Strings(provided)
	if len(provided) > 0 {
		b.WriteString("\n")
		for _, line := range provided {
			b.WriteString(line)
		}
	}
	b.WriteString("}\n\n")

	b.WriteString("// Boot validates the selected closure and constructs typed dependencies in\n")
	b.WriteString("// stable topological order, then starts long-lived services.\n")
	b.WriteString("func Boot(ctx context.Context, h apphost.Host, opts Options) (*Runtime, error) {\n")
	b.WriteString("\tr := &Runtime{}\n")
	b.WriteString("\t_ = h\n")
	provider := make(map[string]string)
	stoppers := make([]string, 0)
	starters := make([]string, 0)
	for _, m := range modules {
		sys := m.Runtime.System
		if sys == nil || sys.Package == "" || sys.Constructor == "" {
			continue
		}
		if err := validateIdentifiers(sys); err != nil {
			return nil, fmt.Errorf("module %s: %w", m.ID, err)
		}
		pkg := goImportName(qualifyPackage(modulePath, sys.Package))
		varName := goVar(m.ID)
		target := varName
		if len(sys.Provides) == 0 && !sys.Stop && !sys.Start {
			// Nothing consumes the result, so binding it would not compile.
			target = "_"
		}
		fmt.Fprintf(&b, "\t%s, err := %s.%s(ctx, h, %s.Deps{\n", target, pkg, sys.Constructor, pkg)
		for _, need := range sys.Needs {
			if !validIdentifier(need.Field) {
				return nil, fmt.Errorf("module %s: invalid need field %q", m.ID, need.Field)
			}
			if expr, ok := provider[need.Capability]; ok {
				fmt.Fprintf(&b, "\t\t%s: %s,\n", need.Field, expr)
				continue
			}
			if isRootCapability(rootNeeds, need) {
				fmt.Fprintf(&b, "\t\t%s: opts.%s,\n", need.Field, need.Field)
				continue
			}
			if need.Optional {
				continue
			}
			return nil, fmt.Errorf("module %s: no module provides capability %q for need %s", m.ID, need.Capability, need.Field)
		}
		b.WriteString("\t})\n")
		b.WriteString("\tif err != nil {\n")
		fmt.Fprintf(&b, "\t\treturn nil, fmt.Errorf(\"boot %s: %%w\", err)\n", goString(m.ID)[1:len(goString(m.ID))-1])
		b.WriteString("\t}\n")
		for _, provide := range sys.Provides {
			if !validIdentifier(provide.Field) {
				return nil, fmt.Errorf("module %s: invalid provide field %q", m.ID, provide.Field)
			}
			field := capabilityField(provide.Capability)
			fmt.Fprintf(&b, "\tr.%s = %s.%s\n", field, varName, provide.Field)
			provider[provide.Capability] = "r." + field
		}
		if sys.Start {
			fmt.Fprintf(&b, "\tr.start = append(r.start, %s.Start)\n", varName)
			starters = append(starters, varName)
		}
		if sys.Stop {
			fmt.Fprintf(&b, "\tr.stop = append(r.stop, %s.Stop)\n", varName)
			stoppers = append(stoppers, varName)
		}
	}
	b.WriteString("\treturn r, nil\n")
	b.WriteString("}\n\n")

	b.WriteString("// Handler returns the composed HTTP handler.\n")
	if handlerField == "" {
		b.WriteString("// The selected graph provides none, so there is nothing to serve.\n")
		b.WriteString("func (r *Runtime) Handler() http.Handler { return nil }\n\n")
	} else {
		fmt.Fprintf(&b, "func (r *Runtime) Handler() http.Handler { return r.%s }\n\n", handlerField)
	}
	b.WriteString("// Run starts every long-lived service in dependency order. Each Start must\n")
	b.WriteString("// return promptly — a module owns its own goroutine — so Run hands control back\n")
	b.WriteString("// to the caller that serves traffic.\n")
	if len(starters) == 0 {
		b.WriteString("func (r *Runtime) Run(ctx context.Context) error { return nil }\n\n")
	} else {
		b.WriteString("func (r *Runtime) Run(ctx context.Context) error {\n")
		b.WriteString("\tfor _, start := range r.start {\n")
		b.WriteString("\t\tif err := start(ctx); err != nil {\n")
		b.WriteString("\t\t\treturn err\n")
		b.WriteString("\t\t}\n")
		b.WriteString("\t}\n")
		b.WriteString("\treturn nil\n")
		b.WriteString("}\n\n")
	}
	b.WriteString("// Close stops services in reverse dependency order. Every stop hook runs\n")
	b.WriteString("// even if an earlier one fails, so one stuck service cannot strand the rest;\n")
	b.WriteString("// the joined error reports all of them.\n")
	b.WriteString("func (r *Runtime) Close(ctx context.Context) error {\n")
	if len(stoppers) == 0 {
		b.WriteString("\treturn nil\n")
		b.WriteString("}\n")
	} else {
		b.WriteString("\tvar errs []error\n")
		b.WriteString("\tfor i := len(r.stop) - 1; i >= 0; i-- {\n")
		b.WriteString("\t\tif err := r.stop[i](ctx); err != nil {\n")
		b.WriteString("\t\t\terrs = append(errs, err)\n")
		b.WriteString("\t\t}\n")
		b.WriteString("\t}\n")
		b.WriteString("\treturn errors.Join(errs...)\n")
		b.WriteString("}\n")
	}

	_ = ctx
	return &GeneratedFile{Path: "internal/modules/bootstrap_registry_gen.go", Content: b.String()}, nil
}

func validateIdentifiers(sys *SystemContribution) error {
	if !validPackagePath(sys.Package) {
		return fmt.Errorf("invalid system package path %q", sys.Package)
	}
	if !validIdentifier(sys.Constructor) {
		return fmt.Errorf("invalid system constructor %q", sys.Constructor)
	}
	return nil
}

// emitTestHostRegistry renders internal/modules/testhost_registry_gen.go. It
// exposes a TestHost used by tests to construct a runtime against a fixture
// lock; Boot never reads this table.
func emitTestHostRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	modules := orderedModules(lock, graph)
	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package modules\n\n")
	b.WriteString("// testHostModules lists the module IDs a test runtime boots with. Boot never\n")
	b.WriteString("// reads this table; test-only items are addressable only here.\n")
	b.WriteString("var testHostModules = []string{\n")
	for _, m := range modules {
		fmt.Fprintf(&b, "\t%s,\n", goString(m.ID))
	}
	b.WriteString("}\n\n")
	b.WriteString("// TestHost returns the module IDs a test runtime boots with.\n")
	b.WriteString("func TestHost() []string { return append([]string{}, testHostModules...) }\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/modules/testhost_registry_gen.go", Content: b.String()}, nil
}

// emitRoutesRegistry renders internal/web/routes_registry_gen.go from every
// selected RouteContribution, in module topological order then lexical ID.
// hasJanitors reports whether any selected module declares a cleanup sweep.
func hasJanitors(graph []Manifest) bool {
	for _, m := range graph {
		if len(m.Runtime.Janitors) > 0 {
			return true
		}
	}
	return false
}

// routePattern is one concrete method+pattern pair awaiting validation.
type routePattern struct {
	id      string
	module  string
	method  string
	pattern string
}

func emitRoutesRegistry(ctx context.Context, modulePath string, lock Lock, graph []Manifest) (*GeneratedFile, error) {
	type route struct {
		moduleID string
		contrib  RouteContribution
		// contentType is non-empty for a route expanded from a content type
		// declaration; its handler resolves the type by id.
		contentType string
	}
	routes := make([]route, 0)
	for _, m := range orderedModules(lock, graph) {
		for _, r := range m.Runtime.Routes {
			routes = append(routes, route{moduleID: m.ID, contrib: r})
		}
		// A content type declares public paths, not routes. Expanding them here
		// is what lets the generator know every pattern and reserved prefix
		// before boot, instead of the router walking a registry at startup.
		for _, ct := range m.Runtime.ContentTypes {
			for _, path := range ct.Paths {
				routes = append(routes, route{moduleID: m.ID, contrib: RouteContribution{
					ID: "content." + ct.ID + ".index", Method: "GET", Pattern: path,
					Scope: RoutePublic, Package: ct.Package, Handler: "handleContentIndex",
				}, contentType: ct.ID})
				if ct.Mode != ContentModePages {
					continue
				}
				routes = append(routes, route{moduleID: m.ID, contrib: RouteContribution{
					ID: "content." + ct.ID + ".detail", Method: "GET", Pattern: path + "/{slug}",
					Scope: RoutePublic, Package: ct.Package, Handler: "handleContentDetail",
				}, contentType: ct.ID})
			}
		}
	}
	sort.Slice(routes, func(i, j int) bool {
		if routes[i].contrib.Pattern != routes[j].contrib.Pattern {
			return routes[i].contrib.Pattern < routes[j].contrib.Pattern
		}
		if routes[i].contrib.Method != routes[j].contrib.Method {
			return routes[i].contrib.Method < routes[j].contrib.Method
		}
		return routes[i].contrib.ID < routes[j].contrib.ID
	})
	if len(routes) == 0 {
		// Nothing contributes a route, so the project has no reason to define the
		// route type this table would reference.
		return nil, nil
	}

	// Every exemption must carry a reason. A bare bool in a diff is a security
	// decision nobody can review.
	for _, r := range routes {
		if r.contrib.Policy.CSRFExempt && strings.TrimSpace(r.contrib.Policy.CSRFReason) == "" {
			return nil, fmt.Errorf(
				"route %s (%s): csrf_exempt requires csrf_reason", r.contrib.ID, r.moduleID)
		}
	}

	// Validate against a real ServeMux. A conflicting or malformed pattern would
	// otherwise panic on the first matching request, long after this generated
	// file was committed and shipped.
	patterns := make([]routePattern, 0, len(routes))
	for _, r := range routes {
		patterns = append(patterns, routePattern{
			id: r.contrib.ID, module: r.moduleID,
			method: r.contrib.Method, pattern: r.contrib.Pattern,
		})
	}
	if err := validateRoutePatterns(patterns); err != nil {
		return nil, err
	}

	var b strings.Builder
	b.WriteString(genHeader(modulePath, lock))
	b.WriteString("package web\n\n")
	b.WriteString("import \"net/http\"\n\n")
	b.WriteString("// RouteRegistry is the complete set of selected routes. Every pattern is a\n")
	b.WriteString("// concrete string known before boot, so the reserved-prefix, sitemap, policy,\n")
	b.WriteString("// and catch-all decisions are all derived from this one table.\n")
	b.WriteString("var RouteRegistry = []Route{\n")
	for _, r := range routes {
		c := r.contrib
		if !validIdentifier(c.Handler) {
			return nil, fmt.Errorf("route %s: handler %q is not a Go identifier", c.ID, c.Handler)
		}
		if c.Enabled != "" && !validIdentifier(c.Enabled) {
			return nil, fmt.Errorf("route %s: enabled %q is not a Go identifier", c.ID, c.Enabled)
		}
		scope, ok := routeScopeConstant(c.Scope)
		if !ok {
			return nil, fmt.Errorf("route %s: scope %q is not a known scope", c.ID, c.Scope)
		}
		fmt.Fprintf(&b, "\t{\n\t\tID: %s, Method: %s, Pattern: %s,\n",
			goString(c.ID), goString(c.Method), goString(c.Pattern))
		fmt.Fprintf(&b, "\t\tScope: %s,\n", scope)
		fmt.Fprintf(&b, "\t\tPolicy: %s,\n", routePolicyLiteral(c.Policy))
		if r.contentType != "" {
			fmt.Fprintf(&b, "\t\tHandler: func(s *Server) http.Handler { return s.%s(%s) },\n",
				c.Handler, goString(r.contentType))
		} else {
			fmt.Fprintf(&b, "\t\tHandler: func(s *Server) http.Handler { return http.HandlerFunc(s.%s) },\n", c.Handler)
		}
		if c.Enabled != "" {
			fmt.Fprintf(&b, "\t\tEnabled: func(s *Server) bool { return s.%s() },\n", c.Enabled)
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n")
	_ = ctx
	return &GeneratedFile{Path: "internal/web/routes_registry_gen.go", Content: b.String()}, nil
}

// routePolicyLiteral renders only the fields that differ from the zero policy,
// so a reader sees the decisions a route actually made.
func routePolicyLiteral(policy RoutePolicy) string {
	parts := make([]string, 0, 7)
	if policy.CSRFExempt {
		parts = append(parts, "CSRFExempt: true")
		parts = append(parts, "CSRFReason: "+goString(policy.CSRFReason))
	}
	if policy.RateExempt {
		parts = append(parts, "RateExempt: true")
	}
	if policy.MaintenanceExempt {
		parts = append(parts, "MaintenanceExempt: true")
	}
	if policy.MaxBodyBytes != 0 {
		parts = append(parts, fmt.Sprintf("MaxBodyBytes: %d", policy.MaxBodyBytes))
	}
	if policy.Idempotent {
		parts = append(parts, "Idempotent: true")
	}
	if policy.AdminWrite {
		parts = append(parts, "AdminWrite: true")
	}
	if len(parts) == 0 {
		return "RoutePolicy{}"
	}
	return "RoutePolicy{" + strings.Join(parts, ", ") + "}"
}

// routeScopeConstant maps a declared scope onto the exported Go constant, so an
// unknown scope is a generation failure rather than an unguarded string.
func routeScopeConstant(scope RouteScope) (string, bool) {
	switch scope {
	case RoutePublic:
		return "ScopePublic", true
	case RouteApp:
		return "ScopeApp", true
	case RouteAdmin:
		return "ScopeAdmin", true
	case RouteAPIRead:
		return "ScopeAPIRead", true
	case RouteAPIWrite:
		return "ScopeAPIWrite", true
	case RouteWebhook:
		return "ScopeWebhook", true
	case RouteStatic:
		return "ScopeStatic", true
	case RouteProbe:
		return "ScopeProbe", true
	case RouteDev:
		return "ScopeDev", true
	}
	return "", false
}

func routeHandlerName(r RouteContribution) string {
	if r.Handler == "" {
		return "noop"
	}
	return r.Handler
}

func routeEnabledName(r RouteContribution) string {
	if r.Enabled == "" {
		return "always"
	}
	return r.Enabled
}

